    "4205": "Wenn aktiviert, erscheint dieselbe Datei innerhalb des gesamten virtuellen Verzeichnisbaums nur einmal. Es gilt das Prinzip \"Später Auswahl hat Vorrang\": Die Datei gehört zu dem zuletzt ausgewählten Label-Verzeichnis (z. B. wenn zuerst A und dann B ausgewählt wird, wird die Datei dem Verzeichnis B zugeordnet). Wenn deaktiviert, können Dateien in mehreren Label-Verzeichnissen mehrfach angezeigt werden.",
