    "7783": "Leichtes Wasserzeichen",
    "7785": "Während des Installationsvorgangs ist ein Fehler aufgetreten. Der KI-Engine fehlen notwendige Dateien, sodass sie im Kompatibilitätsmodus ausgeführt wird. In schweren Fällen kann es zum Absturz des KI-Dienstes kommen.",
    "7786": "Es empfiehlt sich zu prüfen, ob das Installationsverzeichnis über Schreibrechte verfügt. Nachdem Sie sich vergewissert haben, dass kein Problem vorliegt, installieren Sie die Anwendung erneut. Diese Aufforderung wird nicht mehr angezeigt und die KI-Engine mit voller Geschwindigkeit wird den Ladevorgang automatisch fortsetzen.",
    "7788": "Analysemodus auswählen",
    "7789": "Es gibt ein Wasserzeichen",
    "7790": "Der Grad des Wasserzeichens im Dateiinhalt",
    "7791": "Ziehen Sie, um die Spaltenbreite anzupassen",
    "7792": "【In der Warteschlange】",
    "7793": "{count1} Artikel · {count2} Einheiten",
    "7797": "Machen Sie daraus ein separates Fenster",
    "7798": "Auf die unterste Spalte schneiden",
    "7799": "Unabhängiges Fenster",
    "7800": "Untere Spalte",
    "7805": "Fehler-/Übersprungsgrund",
    "7806": "Analysewarteschlange anzeigen – Aktuell: {ws}{name}",
    "7808": "Union",
    "7809": "Überschneidung",
    "7810": "Die Anwendung sammelt nur die notwendigen desensibilisierten Fehlerprotokolle, um Fehler zu beheben und die Benutzererfahrung zu verbessern.",
    "7811": "Von der Cloud zurück in den lokalen Modus gewechselt",
    "7812": "Wenn Sie derzeit das Cloud-Modell verwenden, wird beim Wechsel der folgenden Engines automatisch wieder in den lokalen Modus gewechselt",
    "7813": "Urheberrechtszeichen",
    "7814": "Die Sprache wechselt...bitte warten",
    "7816": "Motorschaltung, Denkmodus",
    "7820": "Klassifizieren Sie Dateien nach Dateityp, extrahieren Sie Miniaturansichten, Metadaten und den gesamten Dokumenttext parallel und nutzen Sie OCR (falls aktiviert).",
    "7824": "Dokumenten- und Inhaltsextraktion",
    "7825": "Größenbeschränkung für die Extraktion von Inhalten (einschließlich OCR).",
    "7826": "Maximale Extraktionsgröße für einen einzelnen Textindikator (Text/Dokument/OCR/HTML). Überlange Inhalte werden automatisch abgeschnitten. Andernfalls wird zu viel Speicherplatz belegt und die Leistung beeinträchtigt.",
    "7827": "Keine Begrenzung",
    "7828": "Zehntausend",
    "7829": "Entspricht etwa {zh} Wörtern oder {en} Wörtern",
    "7830": "Abfangdauer der Audioanalyse",
    "7833": "OCR-Erkennung und -Verarbeitung",
    "7835": "Der Wechsel der KI-Engine ist fehlgeschlagen",
    "7836": "Beste Übereinstimmung",
    "7837": "100 % Leistungsausnutzung",
    "7838": "Garantiert",
    "7839": "Keine Grafikkartenbeschleunigung",
    "7840": "Kompatibilitätsmodus",
    "7841": "70 % Leistungsauslastung",
    "7842": "Lokale KI-Engine wechseln",
    "7843": "Ihre {vendor}-Grafikkarte kann die folgenden Engines umschalten",
    "7844": "KI-Engine",
    "7845": "Anpassungstyp",
    "7846": "Leistungshinweise",
    "7847": "Aktueller Motor",
    "7848": "Wechsel...",
    "7849": "Schalten",
    "7850": "Nach dem Einschalten können lokale und Cloud-Modelle in den Denkmodus wechseln, was möglicherweise die Qualität der KI-Analyse verbessert, aber auch die Reaktionszeit erheblich verlängert.",
    "7874": "Analysewarteschlange",
    "7875": "Wählen Sie den Speicherort des KI-Modells aus",
    "7876": "Das KI-Modell ist die Kerndatei, die der Software intelligente Analysefunktionen ermöglicht und eine große Größe hat.",
    "7877": "Modellspeicherpfad",
    "7878": "Freundliche Tipps",
    "7879": "Verschiedene Modelle können 2–8 GB oder sogar mehr Speicherplatz beanspruchen. Es wird empfohlen, eine Festplatte mit ausreichend verbleibendem Speicherplatz zu wählen.",
    "7880": "Priorisieren Sie SSD (Solid State Drive), was ein schnelleres Laden des Modells und eine reibungslosere KI-Analyse ermöglicht.",
    "7881": "Wählen Sie einfach einen leeren Ordner aus oder erstellen Sie einen neuen. Dies hat keine Auswirkungen auf Ihre vorhandenen Dateien.",
    "7883": "Genauigkeit der OCR-Erkennung",
    "7884": "Wählen Sie die Genauigkeitsstufe der OCR-Texterkennung aus. Extrem schnelle OCR ist für die meisten Szenarien geeignet; Die hochpräzise OCR-Erkennung ist genauer, dauert aber etwas länger.",
    "7885": "Extrem schnelle OCR",
    "7887": "Hochpräzise OCR",
    "7889": "Daten bei erneuter Analyse wiederverwenden",
    "7890": "Wenn die Datei aktualisiert wurde, deaktivieren Sie dieses Element. Andernfalls überspringen Sie diese Informationserfassung, wenn die Grundinformationen einer Datei bereits vorhanden sind. Zu den grundlegenden Informationen gehören: Dateityp, Miniaturansicht, Metadaten und Dateiinhalt.",
    "7891": "Die Analyse wird beschleunigt und Informationen aus der einfachen Klassifizierungsphase werden nicht erneut erfasst.",
    "7892": "Plug-in-Installation: LibreOffice",
    "7895": "Windows-Installationsanleitung ausblenden 💡",
    "7896": "Erweitern Sie das Windows-Installations- und PATH-Konfigurations-Tutorial 💡",
    "7897": "So konfigurieren Sie:",
    "7898": "Bitte fügen Sie zunächst den Installationspfad von LibreOffice zur Umgebungsvariablen PATH des Systems hinzu",
    "7899": "Standardspeicherort:",
    "7900": "Das Modell wechselt, bitte warten",
    "7901": "Die ursprüngliche Datei ging auf der Festplatte verloren oder wurde verschoben",
    "7902": "Verloren gegangen",
    "7903": "Starten Sie nach der Konfiguration die Anwendung neu und klicken Sie erneut auf „Erneut erkennen“.",
    "7905": "Die folgenden Kategorien müssen identifiziert werden und müssen nicht aktiviert werden: Systemverzeichnis, Softwareinstallationsverzeichnis, technische Projekte, Spielpakete, KI-Datensätze/-Modelle, Cache und LFS, virtuelle Umgebung",
    "7906": "Designprojekt: ein Designprojekt, das Projektdateien und Ressourcenverzeichnisse enthält (z. B. .prproj, .aep, .blend)",
    "7907": "Erweiterte KI-Anpassung von Eingabeaufforderungswörtern",
    "7908": "Passen Sie Eingabeaufforderungswörter an, um das Modell zu verfeinern, um die Kategorie zu benennen und die Qualität zu bewerten, und um das Cloud-Modell besser zu empfehlen",
    "7909": "Sollte die KI-Analyse aufgrund zu vieler Wörter fehlschlagen, reduzieren Sie bitte selbst die Wortanzahl. Für lokale kleine Modelle wird empfohlen, maximal 100 Wörter zu enthalten.",
    "7910": "Eingabeaufforderungswort zur Mindesteinheitsidentifizierung (Mindesteinheitsidentifizierung muss aktiviert sein)",
