    "9826": "Bietet für immer kostenlose Modelle, keine Kreditkarte erforderlich.",
    "9829": "Kostenlos, keine Kreditkarte erforderlich. Extrem schnelles Denken (ca. 2600 Token/s). Tageslimit von 1 Million Token. 8K-Kontextbeschränkung für kostenlose Dateien. llama3.1-8b wird voraussichtlich am 27. Mai 2026 veraltet sein.",
