    "9851": "Stellen Sie kostenlosen Benutzern ein monatliches Inferenzdienstkontingent von 100.000 Malen zur Verfügung. Routen zu Anbietern wie Fireworks, Together, Hyperbolic, Nebius, Novita, DeepInfra und mehr. Unterstützt Tausende von Modellen.",
