    "9868": "Melden Sie sich an und erhalten Sie 1 $ kostenloses Guthaben, keine Kreditkarte erforderlich. Mehr als 60 Open-Source-Modelle sind über eine OpenAI-kompatible API verfügbar. Hauptsitz in der EU.",
