    "11508": "Unbegrenzt gültig",
    "11509": "Der Betrag wurde auf dem ursprünglichen Zahlungsweg zurückerstattet, und die Ansprüche aus dem Programm sind erloschen.",
    "11510": "Die Ansprüche wurden vollständig gesichert und werden nach Ablauf des Vollstreckungsplans geltend gemacht.",
