    "11515": "Grundlegende Dienste",
    "11516": "Derzeit nutzen Sie die Basisversion des Dienstes. Durch ein Upgrade auf die Pro- oder Enterprise-Version können Sie den vollen Funktionsumfang sowie die unbegrenzte Dateiverarbeitung freischalten.",
    "11517": "Gerätekennnummer:",
    "11518": "Das Gerät ist durch eine Sicherheitsautorisierung geschützt.",
    "11519": "Gerätekennung kopieren",
    "11520": "Selbstverwaltungsrechnungen und automatische Verlängerung (Kundenportal)",
    "11521": "Über das internationale Kundenportal von Creem können Sie jederzeit frühere Rechnungen und Quittungen herunterladen, die für die Zahlung verwendete Kreditkarte aktualisieren oder die automatische Verlängerung für den nächsten Abrechnungszeitraum deaktivieren. Nach der Deaktivierung bleiben alle Mitgliedervorteile für den laufenden Abrechnungszeitraum unbeeinträchtigt.",
    "11522": "Zum Portal für internationale Abrechnungen, um Rechnungen zu verwalten und zu verlängern",
    "11523": "Den aktuellen Abonnementstatus sofort aus der Cloud abrufen",
    "11524": "Wird synchronisiert...",
    "11525": "Status aktualisieren",
    "11526": "Garantie für die Lizenzierung in festen Zyklen",
    "11527": "Die aktuelle Autorisierung erfolgt im Modus „ohne Kartenbindung mit festem Abrechnungszeitraum“, sodass keinerlei Risiko einer automatischen Abbuchung oder eines Zahlungsabzugs besteht. Nach Ablauf der Autorisierung wird das System nahtlos auf die kostenlose Version zurückgestuft, ohne dass zusätzliche Kosten anfallen. Wenn Sie die Laufzeit verlängern möchten, wenden Sie sich bitte an den Kundenservice.",
    "11528": "Kundendienst:",
    "11529": "E-Mail-Adresse des Kundendienstes kopieren",
    "11530": "Nutzungsbedingungen und Hinweise zu Ihren Rechten",
    "11531": "Exklusiv für die Unternehmensversion",
    "11532": "Aktivierungscode einlösen",
    "11533": "Nachdem Sie auf der offiziellen Website eine Offline-Unternehmenslizenz erworben haben, geben Sie hier den individuellen Lizenzcode ein, um die Aktivierung sofort lokal offline zu überprüfen.",
    "11534": "Meine Gerätekennung",
    "11535": "Zur offiziellen Website, um auf die Pro-Version zu aktualisieren",
    "11536": "Sie können die Pro-Version im Preiscenter auf der offiziellen Website erwerben. Das System wird das aktuelle Gerät anhand dieser Kennung automatisch zuweisen, sodass die Aktivierung sofort in Kraft tritt.",
    "11537": "Die Gerätekennung wurde in die Zwischenablage kopiert.",
    "11538": "Der Link zum Offline-Kauf wurde in die Zwischenablage kopiert",
    "11539": "Die Aktivierung ist fehlgeschlagen. Bitte überprüfen Sie, ob der Autorisierungscode mit dem aktuellen Gerät übereinstimmt.",
    "11540": "Bei der Aktivierung ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.",
    "11541": "Der lokale Offline-Autorisierungsstatus wird gerade synchronisiert...",
    "11542": "Die Autorisierung wurde erfolgreich überprüft. Alle erweiterten Offline-Funktionen für Unternehmen sind nun vollständig freigeschaltet.",
    "11543": "Das Fenster wird in wenigen Sekunden automatisch den Aktivierungszyklus abschließen.",
    "11544": "Schritt 1: Kaufen Sie auf der offiziellen Website eine Offline-Unternehmenslizenz und erhalten Sie den Lizenzschlüssel.",
    "11545": "Besuchen Sie die offizielle Website, um eine Offline-Unternehmenslizenz zu erwerben",
    "11546": "Link wurde kopiert",
    "11547": "Link mit einem Klick kopieren",
    "11548": "Das Gerät ist derzeit offline.",
    "11549": "Die Webseite lässt sich nicht direkt öffnen.",
    "11550": "Bitte klicken Sie auf die Schaltfläche oben, um den Kauf-Link mit einem Klick zu kopieren, und senden Sie ihn an einen Computer oder einen mobilen Browser mit Internetverbindung, um den Kauf abzuschließen. Der Link enthält bereits die Geräte-ID Ihres Geräts; nach der Zahlung wird der entsprechende individuelle Autorisierungscode generiert.",
